package java.lang.reflect;

/**
 * j2zig overlay of java.lang.reflect.Proxy. A native image cannot define classes at run time,
 * so proxy classes are generated by the transpiler (j2zig/program.py: proxy_class) for every
 * interface list it can see statically: all annotation interfaces in the closed world and
 * constant-folded Proxy.newProxyInstance call sites. A proxy class for interfaces I1..In is
 * named {@code jdk.proxy.$J2zProxy<hex(hash("I1;...;In"))>}. Requesting a proxy for any other
 * interface list throws IllegalArgumentException naming the missing proxy class.
 */
public class Proxy implements java.io.Serializable {
    private static final long serialVersionUID = -2222568056686623797L;

    protected InvocationHandler h;

    private Proxy() {}

    protected Proxy(InvocationHandler h) {
        java.util.Objects.requireNonNull(h);
        this.h = h;
    }

    static String j2zProxyName(Class<?>... interfaces) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < interfaces.length; i++) {
            if (i > 0) sb.append(';');
            sb.append(interfaces[i].getName());
        }
        return "jdk.proxy.$J2zProxy" + Integer.toHexString(sb.toString().hashCode());
    }

    @Deprecated
    public static Class<?> getProxyClass(ClassLoader loader, Class<?>... interfaces) throws IllegalArgumentException {
        for (Class<?> i : interfaces) {
            if (!i.isInterface()) throw new IllegalArgumentException(i.getName() + " is not an interface");
        }
        String n = j2zProxyName(interfaces);
        try {
            return Class.forName(n, false, loader);
        } catch (ClassNotFoundException e) {
            throw new IllegalArgumentException("j2zig: no proxy class was generated at build time for "
                    + java.util.Arrays.toString(interfaces) + " (" + n + ")");
        }
    }

    public static Object newProxyInstance(ClassLoader loader, Class<?>[] interfaces, InvocationHandler h) {
        java.util.Objects.requireNonNull(h);
        Class<?> c = getProxyClass(loader, interfaces.clone());
        try {
            return c.getConstructor(InvocationHandler.class).newInstance(h);
        } catch (InvocationTargetException e) {
            Throwable t = e.getCause();
            if (t instanceof RuntimeException r) throw r;
            if (t instanceof Error er) throw er;
            throw new InternalError(t.toString(), t);
        } catch (ReflectiveOperationException e) {
            throw new InternalError(e.toString(), e);
        }
    }

    public static boolean isProxyClass(Class<?> cl) {
        return Proxy.class.isAssignableFrom(cl) && cl.getName().startsWith("jdk.proxy.$J2zProxy");
    }

    public static InvocationHandler getInvocationHandler(Object proxy) throws IllegalArgumentException {
        if (!isProxyClass(proxy.getClass())) throw new IllegalArgumentException("not a proxy instance");
        return ((Proxy) proxy).h;
    }

    private static native Object invokeDefault0(Method method, Object proxy, Object[] args) throws Throwable;

    static Object invokeDefault(Object proxy, Method method, Object[] args, Class<?> caller) throws Throwable {
        if (!isProxyClass(proxy.getClass())) throw new IllegalArgumentException("'proxy' is not a proxy instance");
        if (!method.isDefault()) throw new IllegalArgumentException("\"" + method + "\" is not a default method");
        if (!method.getDeclaringClass().isInstance(proxy))
            throw new IllegalArgumentException("\"" + method + "\" is not a method declared in the proxy class");
        return invokeDefault0(method, proxy, args);
    }
}
